/// <summary>
/// Data provider class for the Sales Order Continuing Permission Notice report.
/// </summary>
/// <remarks>
/// This class extends <c>SrsReportDataProviderBase</c> and is responsible for preparing the data used in the SSRS report
/// for Continuing Permission Notices related to sales orders.
/// It is decorated with <c>SRSReportParameterAttribute</c>, linking it to the <c>METCommonContinuingPermissionNoticeContract</c>
/// which defines the input parameters for the report.
/// Key responsibilities:
/// - Retrieve and transform sales order and excise-related data.
/// - Populate temporary tables with enriched metadata for report rendering.
/// - Support parameter-driven filtering and logic based on business rules.
/// </remarks>
[SRSReportParameterAttribute(classstr(METCommonContinuingPermissionNoticeContract))]
class METSOContinuingPermissionNoticeDP extends SrsReportDataProviderBase
{
    RecordInsertList insertList;
    METSOContinuingPermissionNoticeHeaderTmp header;
    METSOContinuingPermissionNoticeLineTmp line;
    SalesTable salesTable;
    CustInvoiceJour invoiceJour;
    CustInvoiceTrans invoiceTrans;
    METCPNumber num;
    #ISOCountryRegionCodes
    #PrintMgmtSetup

    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerReportGuid;

}

Method.Source:
/// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

/// <summary>
/// Executes the data preparation logic for the Sales Order Continuing Permission Notice report.
/// </summary>
/// <remarks>
/// This method is triggered during SSRS report generation. It performs the following operations:
/// - Retrieves the sales order and associated metadata from <c>SalesTable</c> and <c>METSalesTable</c>.
/// - Identifies the latest invoice transaction linked to the original sales order.
/// - Extracts bond and excise numbers from <c>METCustTable</c>, handling fallback logic if excise number is missing.
/// - Generates a new Continuing Permission Notice number using the <c>METCPNumber</c> number sequence if one doesn't already exist.
/// - Validates the sales order data and inserts header-level information into the temporary reporting table.
/// This logic ensures that each sales order with valid bond and excise details is properly tracked and reported
/// under the Continuing Permission Notice framework.
/// </remarks>
public void processReport()
{
    METCommonContinuingPermissionNoticeContract contract = this.parmDataContract() as METCommonContinuingPermissionNoticeContract;

    SalesId salesId = contract.parmSalesId();
    salesTable =  SalesTable::find(salesId);

    METSalesTable metSalesTable = salesTable.metSalesTable();

    select firstonly invoiceTrans
        order by invoiceTrans.InvoiceDate desc, invoiceTrans.RecId desc
        where invoiceTrans.OrigSalesId == salesTable.SalesId;

    if (invoiceTrans.RecId)
    {
        invoiceJour = invoiceTrans.custInvoiceJour();
    }

    METCustTable metCustTable = METCustTable::find(salesTable.CustAccount);
    List metBondListRec = strSplit(metCustTable.BondNumber, ' ');
    Container metBondConRec = list2con(metBondListRec);

    METBondNumber metBondNumber = conpeek(metBondConRec, 1);
    METExciseNumber metExciseNumber = conpeek(metBondConRec, 2);

    if (!metExciseNumber)
    {
        metExciseNumber = metCustTable.ExciseNumber;
    }

    if (metBondNumber && metExciseNumber)
    {
        if (!metSalesTable.ContinuingPermissionNoticeNumber)
        {
            NumberSequenceReference numberSequenceReference;

            numberSequenceReference = NumberSeqReference::findReference(extendedTypeNum(METCPNumber));

            if (numberSequenceReference.RecId)
            {
                num = NumberSeq::newGetNum(numberSequenceReference).num();
                ttsbegin;
                if (!metSalesTable.SalesTable)
                {
                    metSalesTable.SalesTable = salesTable.RecId;
                    metSalesTable.ContinuingPermissionNoticeNumber = num;
                    metSalesTable.insert();
                }
                else
                {
                    metSalesTable.selectForUpdate(true);
                    metSalesTable.ContinuingPermissionNoticeNumber = num;
                    metSalesTable.update();
                }
                ttscommit;
            }
        }

        if (salesTable.RecId && this.isValidData(salesTable))
        {
            this.insertHeaderData();
        }
    }
}

/// <summary>
/// Validates whether the given SalesTable record has associated data required for excise processing.
/// </summary>
/// <param name="_salesTable">The SalesTable record to validate.</param>
/// <returns>
/// True if the SalesLine exists and is linked to valid InventTable, METInventTable, METTariffItemCodeBase
/// with CustomsExcise type 'C' or 'E', and a corresponding InventDim; otherwise, false.
/// </returns>
/// <remarks>
/// This method ensures that the sales transaction is eligible for excise registration by checking
/// the existence of necessary master data relationships.
/// </remarks>
public boolean isValidData(SalesTable _salesTable)
{
    salesLine salesLine;
    InventTable inventTable;
    METInventTable metInventTable;
    InventDim inventDim;
    METExciseRegisterEntry exciseRegister;
    METTariffItemCodeBase tariffCodeBase;

    select firstonly RecId from salesLine
        where salesLine.SalesId == _salesTable.SalesId
   exists join inventTable
        where salesLine.ItemId == inventTable.ItemId
   exists join metInventTable
        where metInventTable.ItemId == inventTable.ItemId
   exists join tariffCodeBase
        where tariffCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid
        && (tariffCodeBase.CustomsExcise == METCustomExcise::C ||
             tariffCodeBase.CustomsExcise == METCustomExcise::E)
   exists join inventDim
        where inventDim.inventDimId == salesLine.InventDimId;

    return salesLine.RecId != 0 ? true : false;
}

/// <summary>
/// Inserts the report header data.
/// </summary>
public void insertHeaderData()
{
    // 1.Continuing Permission Notice Number
    METSalesTable metSalesTable = salesTable.metSalesTable();

    if (metSalesTable.ContinuingPermissionNoticeNumber)
    {
        header.ContinuingPermissionNoticeNumber = metSalesTable.ContinuingPermissionNoticeNumber;
    }
    else
    {
        header.ContinuingPermissionNoticeNumber = num;
    }

    // 3.Sender
    InventLocation inventLocation;

    select firstonly METWHSubEntity, Name, RecId from inventLocation
        where inventLocation.InventLocationId == salesTable.InventLocationId;

    LogisticsEntityPostalAddressView postalAddressView = this.getWareHousePrimaryAddress(inventLocation.RecId);
    header.SendingBranchName = inventLocation.Name;
    header.SendingBranchAddress = postalAddressView.Address;

    // 4.ABN & Industry key
    METIndustryKeyTable industryKey = METIndustryKeyTable::find(inventLocation.METWHSubEntity);

    header.IndustryKey = industryKey.IndustryKey;
    header.CompanyCoRegNum = METIndustryKeyTable::find(industryKey.IndustryKey).CoRegNum;

    // 2.Logo and Entity name
    header.CompanyName = industryKey.CompanyName;

    // 5.Site Bond/Excise No.
    InventSite site;

    select firstonly METBondNumber from site
        where site.SiteId == salesTable.InventSiteId;

    List metBondList = strSplit(site.METBondNumber, ' ');
    Container metBondCon = list2con(metBondList);

    header.SenderBranchBondNumber = conpeek(metBondCon, 1);
    header.SenderBranchExciseNumber = conpeek(metBondCon, 2);

    // 6.Receiver
    header.ReceivingBranchAddress = CustTable::find(salesTable.CustAccount).postalAddress().Address;
    header.ReceivingBranchName = CustTable::find(salesTable.CustAccount).name();

   // 7. Invoice date and time
    header.InvoiceDateTime = invoiceJour.CreatedDateTime;

    // 8.Customer Bond/Excise No.
    METCustTable metCustTable = METCustTable::find(salesTable.CustAccount);
    List metBondListRec = strSplit(metCustTable.BondNumber, ' ');
    Container metBondConRec = list2con(metBondListRec);

    header.ReceivingBranchBondNumber = metCustTable.BondNumber ;///conpeek(metBondConRec, 1);

    // 9.Receiving branch excise No.
    header.ReceivingBranchExciseNumber = metCustTable.ExciseNumber;////conpeek(metBondConRec, 2);

    // 10. Sales number
    header.SalesId = salesTable.SalesId;

    // 11.Invoice number
    header.InvoiceJourRecId = invoiceJour.RecId;
    header.InvoiceId = invoiceJour.InvoiceId;

    // 12.Bundle fields
    header.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
    header.ContinuingPermissionHeaderGuidStr = headerReportGuid;

    // 13.Report print dates.
    header.NoticeDate = DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::getSystemDateTime(), DateTimeUtil::getUserPreferredTimeZone()));
    header.NoticeTimeString = int2Str(DateTimeUtil::time(DateTimeUtil::utcNow()));

    header.insert();

    this.insertLineData();
}

/// <summary>
/// Prepares and inserts line-level data for the Sales Order Continuing Permission Notice report.
/// </summary>
public void insertLineData()
{
    const str defaultUOM = 'EA';

    SalesLine salesLine;
    InventTable inventTable;
    METInventTable metInventTable;
    InventDim inventDim;
    METExciseRegisterEntry exciseRegister;
    METTariffItemCodeBase tariffCodeBase;
    METSalesLine metSalesLine;
    boolean isMixedItem = false;
    boolean hasMatrix = false;
    boolean hasNoMatrix = false;
    Set unboundSet = new Set(Types::String);

    // To collect all the unbound items and find is it mixed item sales order
    while select salesLine
                where salesLine.SalesId == salesTable.SalesId
                join inventTable
                    where inventTable.ItemId == salesLine.ItemId
                outer join metInventTable
                    where metInventTable.ItemId == inventTable.ItemId
    {  
        if (metInventTable.METTariffItemCodeBaseRecid) 
        {
            hasMatrix = true;
        }
        else 
        {
            unboundSet.add(inventTable.ItemId);
            hasNoMatrix = true;
        }

        // If both conditions true mixed
        if (hasMatrix && hasNoMatrix)
        {
            isMixedItem = true;
        }
    }


    // Initialize batch insert list for temporary CP notice lines
    insertList = new RecordInsertList(tableNum(METSOContinuingPermissionNoticeLineTmp), false, false, false, false, false, line);

    // Loop through sales lines and join related metadata
    while select salesLine
        where salesLine.SalesId == salesTable.SalesId
    join inventTable
        where salesLine.ItemId == inventTable.ItemId
    outer join metInventTable
        where metInventTable.ItemId == inventTable.ItemId
    outer join TariffItem from tariffCodeBase
        where tariffCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid
        && (tariffCodeBase.CustomsExcise == METCustomExcise::C || tariffCodeBase.CustomsExcise == METCustomExcise::E)
    outer join RecId from inventDim
        where inventDim.inventDimId == salesLine.InventDimId
    outer join RecId, Lodgement, BottleSupplied from metSalesLine
        where metSalesLine.SalesLine == salesLine.RecId
    {

        // Filtering for unbound items in mixed item sales order
        if (!(isMixedItem && unboundSet.in(inventTable.ItemId)))
        {
            List lodgementList = new List(Types::Container);

            // If lodgement and bottle data exist, pair them into a container list
            if (metSalesLine.Lodgement && metSalesLine.BottleSupplied)
            {
                List lodgementSplit = strSplit(metSalesLine.Lodgement, ',');
                List bottleSplit = strSplit(metSalesLine.BottleSupplied, ',');

                ListEnumerator lodgementEnum = lodgementSplit.getEnumerator();
                ListEnumerator bottleEnum = bottleSplit.getEnumerator();

                while (lodgementEnum.moveNext() && bottleEnum.moveNext())
                {
                    METLodgement lodgementId = any2Str(lodgementEnum.current());
                    real bottlesSupplied = str2num(any2Str(bottleEnum.current()));

                    lodgementList.addEnd([lodgementId, bottlesSupplied]);
                }
            }
            else
            {
                // If no data exists, calculate lodgement distribution dynamically
                lodgementList = this.getMetLodgement(
                salesLine.ItemId,
                salesLine.inventDim().InventSiteId,
                salesLine.QtyOrdered);
            }

            // Iterate each lodgement entry and call prepareRecordListTmp
            if (!lodgementList.empty())
            {
                // Iterate each lodgement entry and call prepareRecordListTmp
                ListEnumerator enum = lodgementList.getEnumerator();
                while (enum.moveNext())
                {
                    container pair = enum.current();
                    METLodgement lodgementId = conPeek(pair, 1);
                    NumberOf bottleQty = conPeek(pair, 2);

                    this.prepareRecordListTmp(salesLine,
                                            inventTable,
                                            metInventTable,
                                            tariffCodeBase,
                                            lodgementList,
                                            lodgementId,
                                            bottleQty,
                                            true);
                }
            }
            else
            {
                // Handle case when no lodgements are available
                List emptyList = new List(Types::Container);
                this.prepareRecordListTmp(salesLine,
                                        inventTable,
                                        metInventTable,
                                        tariffCodeBase,
                                        emptyList, // or an empty List if required
                                        '',   // empty lodgementId
                                        0,    // zero bottleQty
                                        false);
            }
        }

    }

    // Finalize batch insert into temporary table
    insertList.insertDatabase();
}

/// <summary>
/// dsHeader
/// </summary>
/// <returns>METSOContinuingPermissionNoticeHeaderTmp</returns>
[SRSReportDataSetAttribute(tableStr(METSOContinuingPermissionNoticeHeaderTmp))]
public METSOContinuingPermissionNoticeHeaderTmp dsHeader()
{
    select header;

    return header;
}

/// <summary>
/// dsLines
/// </summary>
/// <returns>METSOContinuingPermissionNoticeLineTmp</returns>
[SRSReportDataSetAttribute(tableStr(METSOContinuingPermissionNoticeLineTmp))]
public METSOContinuingPermissionNoticeLineTmp dsLines()
{
    select line;

    return line;
}

