/// <summary>
/// Get WareHouse address By recevingdock role
/// </summary>
/// <param name = "_inventLocationRecId">Location RecId</param>
/// <param name = "_roleRecId">Role Recid</param>
/// <param name = "_type">LogisticsElectronicAddressMethodType</param>
/// <returns>Locator</returns>
private LogisticsEntityPostalAddressView getWareHousePrimaryAddress(RefRecId _inventLocationRecId)
{
    LogisticsEntityPostalAddressView  logisticsEntityPostalAddressView;

    select firstonly Address from logisticsEntityPostalAddressView
        where logisticsEntityPostalAddressView.Entity == _inventLocationRecId
        && logisticsEntityPostalAddressView.EntityType == LogisticsLocationEntityType::Warehouse
        && logisticsEntityPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.IsPrimary == NoYes::Yes;

    return logisticsEntityPostalAddressView;
}

/// <summary>
/// Allocates sales line quantity across open lodgements in chronological order.
/// Updates available quantity and lodgement status, and returns a list of [Lodgement ID, Bottles Supplied].
/// </summary>
/// <param name="_itemId">Item ID to allocate lodgements for.</param>
/// <param name="_siteId">Site ID where lodgements are stored.</param>
/// <param name="_salesLineQty">Quantity to be fulfilled from lodgements.</param>
/// <returns>
/// A List of containers, each containing [Lodgement ID, Bottles Supplied].
/// </returns>
private List getMetLodgement(ItemId _itemId, InventSiteId _siteId, Qty _salesLineQty)
{
    List resultList = new List(Types::Container);
    METExciseInformationTable metExciseInformationTablePO;
    real remainingQty = abs(_salesLineQty);

    ttsbegin;

    // Select open lodgements in chronological order
    while select forupdate metExciseInformationTablePO
        order by CreatedDateTime asc
            where (metExciseInformationTablePO.InventTransType == InventTransType::Purch ||
                metExciseInformationTablePO.InventTransType == InventTransType::TransferOrderReceive) &&
                metExciseInformationTablePO.ItemId == _itemId &&
                metExciseInformationTablePO.SiteId == _siteId &&
                metExciseInformationTablePO.AvailableQty > 0 &&
                metExciseInformationTablePO.LodgementClosed == NoYes::No
    {
        if (remainingQty <= 0)
        {
            break; // Stop if required quantity is fulfilled
        }

        real availableQtyBefore = metExciseInformationTablePO.AvailableQty;
        real bottlesSupplied = 0;

        if (remainingQty >= availableQtyBefore)
        {
            bottlesSupplied = availableQtyBefore;
            remainingQty -= availableQtyBefore;

            metExciseInformationTablePO.AvailableQty = 0;
            metExciseInformationTablePO.LodgementClosed = NoYes::Yes;
        }
        else
        {
            bottlesSupplied = remainingQty;
            metExciseInformationTablePO.AvailableQty = availableQtyBefore - remainingQty;
            remainingQty = 0;
        }

        metExciseInformationTablePO.update();

        resultList.addEnd([metExciseInformationTablePO.Lodgement, bottlesSupplied]);
    }

    ttscommit;

    return resultList;
}

/// <summary>
/// Prepares and inserts a temporary line record for the sales order continuing permission notice.
/// </summary>
/// <param name="_salesLine">The sales line being processed.</param>
/// <param name="_inventTable">The item master record associated with the sales line.</param>
/// <param name="_metInventTable">Extended item metadata including bottle size, alcohol content, and pack quantity.</param>
/// <param name="_tariffCodeBase">Tariff item code details for customs and excise reporting.</param>
/// <param name="_lodgement">List of containers [Lodgement, BottlesSupplied].</param>
/// <param name="_metLodgement">The last lodgement used for excise lookup.</param>
/// <param name="_bottleQty">Bottle quantity associated with the last lodgement.</param>
/// <param name="_isLodgement">Flag indicating whether lodgement logic is applied.</param>
/// <param name="_availableQty">Total available quantity (used only if _isLodgement is true).</param>
private void prepareRecordListTmp(
SalesLine _salesLine,
InventTable _inventTable,
METInventTable _metInventTable,
METTariffItemCodeBase _tariffCodeBase,
List _lodgement,
METLodgement _metLodgement,
NumberOf _bottleQty,
boolean _isLodgement)
{
    const str defaultUOM = 'EA';

    METExciseRegisterEntry exciseRegister;
    METSalesLine metSalesLine;

    str lodgementStr = '';
    str bottleStr = '';

    // Build comma-separated strings from lodgement list
    ListEnumerator enum = _lodgement.getEnumerator();
    while (enum.moveNext())
    {
        container pair = enum.current();
        METLodgement lodgementId = conPeek(pair, 1);
        real bottleQty = conPeek(pair, 2);

        lodgementStr = lodgementStr == '' ? lodgementId : strFmt('%1,%2', lodgementStr, lodgementId);
        bottleStr = bottleStr == '' ? strFmt('%1', bottleQty) : strFmt('%1,%2', bottleStr, bottleQty);
    }

    // Update or insert METSalesLine with comma-separated values
    if (!_lodgement.empty())
    {
        select firstonly metSalesLine
        where metSalesLine.SalesLine == _salesLine.RecId;

        if (metSalesLine.RecId)
        {
            ttsbegin;
            metSalesLine.selectForUpdate(true);
            metSalesLine.Lodgement = lodgementStr;
            metSalesLine.BottleSupplied = bottleStr;
            metSalesLine.update();
            ttscommit;
        }
        else
        {
            metSalesLine.SalesLine = _salesLine.RecId;
            metSalesLine.Lodgement = lodgementStr;
            metSalesLine.BottleSupplied = bottleStr;
            metSalesLine.insert();
        }
    }

    // Use last lodgement for BondMark and excise lookup
    line.BondMark = _metLodgement;

    exciseRegister = METExciseRegisterEntry::find(
    _metLodgement,
    _salesLine.inventDim().InventSiteId,
    _salesLine.ItemId);

    // Convert sales quantity to bottles using UOM conversion
    METPurchaseWMSFactor purchaseWMSFactor = UnitOfMeasureConversion::findByConversion(
    UnitOfMeasure::findBySymbol(_salesLine.SalesUnit).RecId,
    UnitOfMeasure::findBySymbol(defaultUOM).RecId,
    EcoResProduct::findByProductNumber(_salesLine.ItemId).RecId).Factor;

    // Populate the temporary line record
    line.BottlesSupplied = _isLodgement ? abs(_bottleQty) : abs(purchaseWMSFactor * _salesLine.SalesQty);
    line.ItemId = _salesLine.ItemId;
    line.ItemDescription = _inventTable.productName(SystemParameters::getSystemLanguageId());
    line.BottleSize = _metInventTable.BottleSize;
    line.PackQty = _metInventTable.ItemPack;
    line.Strength = _metInventTable.AlcoholContent;
    line.SalesUoM = _salesLine.SalesUnit;
    line.Quantity = _salesLine.SalesQty;
    line.LitresOfAlcoholCalculated = abs(_metInventTable.BottleSize * line.BottlesSupplied * (_metInventTable.AlcoholContent / 100));
    line.ValueTIU = exciseRegister.TIUV;
    line.TariffItem = _tariffCodeBase.TariffItem;
    line.CountryOfOrigin = _metInventTable.CountryCode;
    line.StatCode = _metInventTable.statcode();
    line.ValueDuty = exciseRegister.DutyRateReceived;
    line.InvoiceAccount = salesTable.InvoiceAccount;
    line.SalesId = salesTable.SalesId;
    line.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
    line.ContinuingPermissionHeaderGuidStr = headerReportGuid;

    // Add the populated line to the insert list for batch processing
    insertList.add(line);
}
